15	      typeof renderedValue === 'object' ||
16	      typeof renderedValue === 'undefined',
17	    '"llm-rubric" assertion type must have a string or object value',
18	  );
19	  if (test.options?.rubricPrompt && typeof test.options.rubricPrompt === 'object') {
20	    test.options.rubricPrompt = JSON.stringify(test.options.rubricPrompt);
21	  }
22	
23	  // Update the assertion value. This allows the web view to display the prompt.
24	  assertion.value = assertion.value || test.options?.rubricPrompt;
25	
26	  return matchesLlmRubric(
27	    renderedValue || '',
28	    outputString,
29	    test.options,
30	    test.vars,
31	    assertion,
32	    undefined,
33	    providerCallContext,
34	  );
35	};
