import { matchesLlmRubric } from '../matchers/llmGrading';
import invariant from '../util/invariant';

import type { AssertionParams, GradingResult } from '../types/index';

export const handleLlmRubric = async ({
  assertion,
  inverse,
  renderedValue,
  outputString,
  test,
  providerCallContext,
}: AssertionParams): Promise<GradingResult> => {
  invariant(
    typeof renderedValue === 'string' ||
      typeof renderedValue === 'object' ||
      typeof renderedValue === 'undefined',
    '"llm-rubric" assertion type must have a string or object value',
  );
  if (test.options?.rubricPrompt && typeof test.options.rubricPrompt === 'object') {
    test.options.rubricPrompt = JSON.stringify(test.options.rubricPrompt);
  }

  // Update the assertion value. This allows the web view to display the prompt.
  assertion.value = assertion.value || test.options?.rubricPrompt;

  const result = await matchesLlmRubric(
    renderedValue || '',
    outputString,
    test.options,
    test.vars,
    assertion,
    undefined,
    providerCallContext,
  );

  if (!inverse) {
    return result;
  }

  // A grader transport/parse failure is not evidence for or against the
  // criterion, so `not-llm-rubric` must propagate it verbatim rather than
  // flipping it into a spurious pass.
  if (result.metadata?.graderError === true) {
    return { ...result, assertion };
  }

  const baseScore =
    typeof result.score === 'number' && !Number.isNaN(result.score) ? result.score : 0;
  const invertedScore = Math.max(0, Math.min(1, 1 - baseScore));

  return {
    ...result,
    assertion,
    pass: !result.pass,
    score: invertedScore,
  };
};

